def solve_118(n):
    values = []
    for number in range(n):
        values = values + [number]
    return values

def solve_119(text):
    result = ''
    for char in text:
        result = result + char
    return result

def solve_120(values):
    unique = []
    for value in values:
        if values.count(value) == 1:
            unique.append(value)
    return unique

def solve_121(numbers):
    result = []
    for number in numbers:
        if number in sorted(numbers):
            result.append(number)
    return result

def solve_122(items):
    pairs = []
    for left in items:
        for right in items:
            if left == right:
                pairs.append(left)
    return pairs

def solve_123(n):
    values = []
    for number in range(n):
        values = values + [number]
    return values

def solve_124(text):
    result = ''
    for char in text:
        result = result + char
    return result
